"""Dataset loader, preprocessor, and chronological window splitter for Polymarket 5m ML."""

from pathlib import Path
from typing import Dict, List, Optional, Tuple

import joblib
import numpy as np
import pandas as pd
import torch
from sklearn.preprocessing import StandardScaler
from torch.utils.data import DataLoader, TensorDataset

# Explicit list of numerical feature columns generated by FeatureBuilder
FEATURE_COLS: List[str] = [
    # Time features
    "secondsRemaining",
    "fractionElapsed",
    # BTC Price & Multi-scale Returns
    "btcPrice",
    "btcReturn1s",
    "btcReturn5s",
    "btcReturn15s",
    "btcReturn60s",
    "btcReturn300s",
    # BTC Realized Volatility
    "btcVol5s",
    "btcVol15s",
    "btcVol60s",
    # BTC Orderbook & Spreads
    "btcBid",
    "btcAsk",
    "btcSpread",
    "btcMid",
    # BTC Volume dynamics
    "btcVolumeDelta5s",
    "btcBuySellRatio",
    "btcNetVolume",
    # Chainlink Reference signals
    "chainlinkPrice",
    "chainlinkReturn5s",
    "chainlinkReturn15s",
    "chainlinkBinanceBasis",
    # Polymarket UP outcome orderbook
    "upBid",
    "upAsk",
    "upMid",
    "upSpread",
    "upBidSize",
    "upAskSize",
    "upOrderBookImbalance",
    "upLastTradePrice",
    # Polymarket DOWN outcome orderbook
    "downBid",
    "downAsk",
    "downMid",
    "downSpread",
    "downBidSize",
    "downAskSize",
    "downOrderBookImbalance",
    "downLastTradePrice",
    # Market Inefficiency signals
    "upDownSpreadSum",
    "pmImpliedProbUp",
]

TARGET_COL: str = "target"


def load_dataset(csv_path: str = "data/dataset/dataset.csv") -> pd.DataFrame:
    """Loads dataset from CSV file and performs basic integrity checks."""
    path = Path(csv_path)
    if not path.exists():
        raise FileNotFoundError(
            f"Dataset file '{csv_path}' not found. Run 'npm run dataset:build' first."
        )

    df = pd.read_csv(path)
    # Ensure chronological order
    df = df.sort_values("timestampMs").reset_index(drop=True)

    # Filter available features
    available_features = [col for col in FEATURE_COLS if col in df.columns]
    if len(available_features) < 10:
        raise ValueError(
            f"Expected at least 10 features, found {len(available_features)}. Check dataset schema."
        )

    # Fill any NaNs or Infs
    df[available_features] = df[available_features].replace([np.inf, -np.inf], np.nan)
    df[available_features] = df[available_features].ffill().bfill().fillna(0.0)

    return df


def split_by_market_window(
    df: pd.DataFrame,
    train_ratio: float = 0.70,
    val_ratio: float = 0.15,
) -> Tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """Splits dataset strictly by market window (slug) in chronological order.

    Never shuffles across time, preventing future data leakage into the training set.
    """
    unique_slugs = df["slug"].drop_duplicates().tolist()
    total_windows = len(unique_slugs)

    # When there are enough windows (>= 10), split by whole windows
    if total_windows >= 10:
        n_train_windows = max(1, int(total_windows * train_ratio))
        n_val_windows = max(1, int(total_windows * val_ratio))

        train_slugs = set(unique_slugs[:n_train_windows])
        val_slugs = set(unique_slugs[n_train_windows : n_train_windows + n_val_windows])
        test_slugs = set(unique_slugs[n_train_windows + n_val_windows :])

        if not test_slugs and len(val_slugs) > 1:
            moved = val_slugs.pop()
            test_slugs.add(moved)

        df_train = df[df["slug"].isin(train_slugs)].reset_index(drop=True)
        df_val = df[df["slug"].isin(val_slugs)].reset_index(drop=True)
        df_test = df[df["slug"].isin(test_slugs)].reset_index(drop=True)

        if len(df_train[TARGET_COL].unique()) > 1 or len(df[TARGET_COL].unique()) == 1:
            return df_train, df_val, df_test

    # For early runs or small datasets (< 10 windows), split each window
    # chronologically (e.g. 70% early phase, 15% mid phase, 15% late phase).
    # This guarantees zero lookahead while ensuring both classes are represented in train.
    train_parts = []
    val_parts = []
    test_parts = []

    for slug in unique_slugs:
        w_df = df[df["slug"] == slug].sort_values("timestampMs").reset_index(drop=True)
        nw = len(w_df)
        if nw < 3:
            train_parts.append(w_df)
            continue
        n_tr = max(1, int(nw * train_ratio))
        n_v = max(1, int(nw * val_ratio))
        train_parts.append(w_df.iloc[:n_tr])
        val_parts.append(w_df.iloc[n_tr : n_tr + n_v])
        test_parts.append(w_df.iloc[n_tr + n_v :])

    df_train = pd.concat(train_parts, ignore_index=True) if train_parts else df.iloc[:0]
    df_val = pd.concat(val_parts, ignore_index=True) if val_parts else df.iloc[:0]
    df_test = pd.concat(test_parts, ignore_index=True) if test_parts else df.iloc[:0]

    return df_train, df_val, df_test


def prepare_ml_data(
    csv_path: str = "data/dataset/dataset.csv",
    train_ratio: float = 0.70,
    val_ratio: float = 0.15,
    scaler_save_path: Optional[str] = "ml/checkpoints/scaler.joblib",
) -> Dict:
    """Loads dataset, splits chronologically, scales features, and creates PyTorch loaders."""
    df = load_dataset(csv_path)
    feature_cols = [c for c in FEATURE_COLS if c in df.columns]

    df_train, df_val, df_test = split_by_market_window(
        df, train_ratio=train_ratio, val_ratio=val_ratio
    )

    X_train = df_train[feature_cols].values.astype(np.float32)
    y_train = df_train[TARGET_COL].values.astype(np.float32)

    X_val = df_val[feature_cols].values.astype(np.float32)
    y_val = df_val[TARGET_COL].values.astype(np.float32)

    X_test = df_test[feature_cols].values.astype(np.float32)
    y_test = df_test[TARGET_COL].values.astype(np.float32)

    # Scale features using only training statistics (no data leakage)
    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train)
    X_val_scaled = scaler.transform(X_val) if len(X_val) > 0 else X_val
    X_test_scaled = scaler.transform(X_test) if len(X_test) > 0 else X_test

    if scaler_save_path:
        Path(scaler_save_path).parent.mkdir(parents=True, exist_ok=True)
        joblib.dump(scaler, scaler_save_path)

    return {
        "feature_cols": feature_cols,
        "scaler": scaler,
        "X_train": X_train_scaled,
        "y_train": y_train,
        "X_val": X_val_scaled,
        "y_val": y_val,
        "X_test": X_test_scaled,
        "y_test": y_test,
        "df_train": df_train,
        "df_val": df_val,
        "df_test": df_test,
    }


def create_dataloaders(
    prepared_data: Dict,
    batch_size: int = 64,
) -> Tuple[DataLoader, Optional[DataLoader], Optional[DataLoader]]:
    """Wraps prepared numpy arrays into PyTorch DataLoaders."""
    train_dataset = TensorDataset(
        torch.tensor(prepared_data["X_train"], dtype=torch.float32),
        torch.tensor(prepared_data["y_train"], dtype=torch.float32).unsqueeze(1),
    )
    train_loader = DataLoader(train_dataset, batch_size=batch_size, shuffle=True)

    val_loader = None
    if len(prepared_data["X_val"]) > 0:
        val_dataset = TensorDataset(
            torch.tensor(prepared_data["X_val"], dtype=torch.float32),
            torch.tensor(prepared_data["y_val"], dtype=torch.float32).unsqueeze(1),
        )
        val_loader = DataLoader(val_dataset, batch_size=batch_size, shuffle=False)

    test_loader = None
    if len(prepared_data["X_test"]) > 0:
        test_dataset = TensorDataset(
            torch.tensor(prepared_data["X_test"], dtype=torch.float32),
            torch.tensor(prepared_data["y_test"], dtype=torch.float32).unsqueeze(1),
        )
        test_loader = DataLoader(test_dataset, batch_size=batch_size, shuffle=False)

    return train_loader, val_loader, test_loader
